-- | Registry: <https://registry.khronos.org/vulkan/specs/latest/man/html/vkCmdSetSampleMaskEXT.html vkCmdSetSampleMaskEXT>
-- Available: VK_EXT_extended_dynamic_state3,VK_EXT_shader_object
cmdSetSampleMaskEXT
  :: forall m
   . (MonadIO m)
  => CommandBuffer
  -> Flags SampleCountFlagBits
  -> Maybe (V.Vector SampleMask)
  -> m ()
cmdSetSampleMaskEXT commandBuffer samples sampleMask =
  liftIO $ withArena \arena_ -> runAlloc arena_ do
    p_sampleMask <-
      maybe
        (pure nullPtr)
        ( \v_ -> do
            pv_ <- arenaBytes (4 * max 1 (V.length v_)) 4
            liftIO (V.imapM_ (\i v_e -> pokeByteOff pv_ (i * 4) (fromIntegral v_e :: Word32)) v_)
            pure (castPtr pv_ :: Ptr ())
        )
        sampleMask
    liftIO
      ( mkCmdSetSampleMaskEXT
          (checkCommandPtr "vkCmdSetSampleMaskEXT" commandBuffer.cmds.pCmdSetSampleMaskEXT)
          (castPtr commandBuffer.handle)
          ((\(Flags w) -> w) samples)
          p_sampleMask
      )
    pure ()

